CREATE OR REPLACE FUNCTION public.admin_set_contacts(p_name1 text, p_num1 text, p_name2 text DEFAULT NULL::text, p_num2 text DEFAULT NULL::text, p_name3 text DEFAULT NULL::text, p_num3 text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  n1 text; w1 text; n2 text; w2 text; n3 text; w3 text;
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;
  n1 := btrim(regexp_replace(coalesce(p_name1, ''), '\s+', ' ', 'g'));
  n2 := btrim(regexp_replace(coalesce(p_name2, ''), '\s+', ' ', 'g'));
  n3 := btrim(regexp_replace(coalesce(p_name3, ''), '\s+', ' ', 'g'));
  w1 := regexp_replace(coalesce(p_num1, ''), '[^0-9]', '', 'g');          -- allows "+91 62352 02168"
  w2 := regexp_replace(coalesce(p_num2, ''), '[^0-9]', '', 'g');
  w3 := regexp_replace(coalesce(p_num3, ''), '[^0-9]', '', 'g');

  -- contact 1 is required: both name and number
  if n1 = '' or w1 = '' then
    raise exception 'FIRST_CONTACT_REQUIRED' using detail = 'contact 1';
  end if;
  if char_length(n1) > 40 then raise exception 'INVALID_CONTACT_NAME' using detail = 'contact 1'; end if;
  if w1 !~ '^[0-9]{11,15}$' then raise exception 'INVALID_WHATSAPP' using detail = 'contact 1'; end if;

  -- contacts 2 and 3 are optional, but name and number come together
  if (n2 = '') <> (w2 = '') then raise exception 'CONTACT_INCOMPLETE' using detail = 'contact 2'; end if;
  if n2 <> '' then
    if char_length(n2) > 40 then raise exception 'INVALID_CONTACT_NAME' using detail = 'contact 2'; end if;
    if w2 !~ '^[0-9]{11,15}$' then raise exception 'INVALID_WHATSAPP' using detail = 'contact 2'; end if;
  end if;
  if (n3 = '') <> (w3 = '') then raise exception 'CONTACT_INCOMPLETE' using detail = 'contact 3'; end if;
  if n3 <> '' then
    if char_length(n3) > 40 then raise exception 'INVALID_CONTACT_NAME' using detail = 'contact 3'; end if;
    if w3 !~ '^[0-9]{11,15}$' then raise exception 'INVALID_WHATSAPP' using detail = 'contact 3'; end if;
  end if;

  -- one single update: all three contacts are saved together or not at all
  update settings set
    contact1_name   = n1,
    whatsapp_number = w1,
    contact2_name   = nullif(n2, ''),
    contact2_number = nullif(w2, ''),
    contact3_name   = nullif(n3, ''),
    contact3_number = nullif(w3, '')
  where id = 1;
end $function$;

