CREATE OR REPLACE FUNCTION public.log_ticket_activity(p_code text, p_phone text, p_action text, p_tickets text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; ph text; b bookings%rowtype; t record; n integer := 0;
begin
  c  := replace(replace(replace(upper(coalesce(p_code, '')), 'O', '0'), ' ', ''), '-', '');
  ph := replace(replace(coalesce(p_phone, ''), ' ', ''), '-', '');
  if length(c) <> 8 or ph !~ '^[0-9]{10}$'
     or p_action is null or p_action not in ('view','jpg','pdf','all-pdf')
     or (p_tickets is not null and cardinality(p_tickets) > 10) then
    return jsonb_build_object('ok', true, 'logged', 0);
  end if;
  select * into b from bookings where booking_code = c;
  if not found or b.status <> 'paid' then return jsonb_build_object('ok', true, 'logged', 0); end if;
  if b.kind = 'transfer' and not exists (select 1 from transfer_buyers x where x.booking_id = b.id and x.phone = ph) then
    return jsonb_build_object('ok', true, 'logged', 0);
  end if;
  for t in
    select k.id from tickets k
    where k.booking_id = b.id and k.phone = ph
      and k.transferred_out_at is null
      and (k.ticket_no is not null or k.coord_no is not null)
      and (p_tickets is null or _ticket_label(k.kind, k.ticket_no, k.coord_no) = any(p_tickets))
    order by k.reg_seq
  loop
    if p_action = 'view' and exists (select 1 from ticket_activity a
         where a.ticket_id = t.id and a.action = 'view' and a.created_at > now() - interval '10 minutes') then
      continue;
    end if;
    insert into ticket_activity (ticket_id, action) values (t.id, p_action);
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'logged', n);
end $function$;

CREATE OR REPLACE FUNCTION public.lookup_tickets(p_code text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b bookings%rowtype; c text; ph text; tk jsonb; bu transfer_buyers%rowtype; x transfers%rowtype; st text; gm_on boolean;
begin
  c  := replace(replace(replace(upper(coalesce(p_code, '')), 'O', '0'), ' ', ''), '-', '');
  ph := replace(replace(coalesce(p_phone, ''), ' ', ''), '-', '');
  if length(c) <> 8 or ph !~ '^[0-9]{10}$' then return jsonb_build_object('found', false); end if;
  select show_messages into gm_on from settings where id = 1;
  select * into b from bookings where booking_code = c;
  if not found then return jsonb_build_object('found', false); end if;
  if b.kind = 'transfer' then
    select * into bu from transfer_buyers where booking_id = b.id and phone = ph;
    if not found then return jsonb_build_object('found', false); end if;
    select * into x from transfers where id = bu.transfer_id;
  end if;
  select jsonb_agg(jsonb_build_object(
           'ticket_no', t.ticket_no, 'kind', t.kind, 'coord_no', t.coord_no,
           'label', _ticket_label(t.kind, t.ticket_no, t.coord_no),
           'secret', case when b.status = 'paid' and t.transferred_out_at is null then t.secret else null end,
           'game_message', case when gm_on and b.status = 'paid' and t.transferred_out_at is null
                                then (select m.body from ticket_messages tm join game_messages m on m.id = tm.message_id where tm.ticket_id = t.id) else null end,
           'game_prize', case when gm_on and b.status = 'paid' and t.transferred_out_at is null
                              then (select z.body from ticket_prizes z where z.ticket_id = t.id) else null end,
           'game_prize_heading', case when gm_on and b.status = 'paid' and t.transferred_out_at is null
                              then (select z.heading from ticket_prizes z where z.ticket_id = t.id) else null end,
           'transferred', (t.transferred_out_at is not null),
           'name', t.name, 'location', t.location, 'attendance', t.attendance, 'food', t.food)
         order by t.reg_seq)
    into tk from tickets t where t.booking_id = b.id and t.phone = ph;
  if tk is null then
    if b.kind = 'transfer' then
      st := case when x.kind = 'public' and x.returned_at is not null then 'returned'
                 when x.kind = 'public' and x.return_due then 'return_due'
                 when b.status = 'rejected' then 'rejected'
                 when x.kind = 'public' and x.payment_verified_at is not null then 'payment_verified'
                 when x.kind = 'public' and x.payment_submitted_at is not null then 'payment_submitted'
                 when x.kind = 'public' and x.payment_requested_at is not null then 'payment_due'
                 else 'pending' end;
      return jsonb_build_object('found', true, 'kind', 'transfer', 'booking_code', b.booking_code, 'status', b.status,
                                'people_count', 1, 'amount_expected', 0, 'name', bu.name, 'tickets', '[]'::jsonb,
                                'transfer', jsonb_build_object('type', x.kind, 'state', st,
                                   'amount_due', case when st = 'payment_due' then x.amount_due end));
    end if;
    return jsonb_build_object('found', false);
  end if;
  return jsonb_build_object('found', true, 'kind', b.kind, 'booking_code', b.booking_code, 'status', b.status,
                            'people_count', b.people_count, 'amount_expected', b.amount_expected, 'tickets', tk);
end $function$;

CREATE OR REPLACE FUNCTION public.private_sell(p_booking_code text, p_ticket text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; tid uuid; t tickets%rowtype; b bookings%rowtype; x transfers%rowtype; code text; lbl text;
begin
  select * into s from settings where id = 1;
  if not s.transfers_open then return jsonb_build_object('ok', false, 'error', 'TRANSFERS_CLOSED'); end if;
  if s.transfer_cutoff_at is not null and now() > s.transfer_cutoff_at then
    return jsonb_build_object('ok', false, 'error', 'CUTOFF_PASSED'); end if;
  tid := _find_seller_ticket(p_booking_code, p_ticket, p_phone);
  if tid is null then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into t from tickets where id = tid for update;
  select * into b from bookings where id = t.booking_id;
  if t.transferred_out_at is not null then return jsonb_build_object('ok', false, 'error', 'ALREADY_TRANSFERRED'); end if;
  if b.status <> 'paid' or (t.ticket_no is null and t.coord_no is null) then return jsonb_build_object('ok', false, 'error', 'NOT_CONFIRMED'); end if;
  if t.checked_in_at is not null then return jsonb_build_object('ok', false, 'error', 'ALREADY_CHECKED_IN'); end if;
  lbl := _ticket_label(t.kind, t.ticket_no, t.coord_no);

  select * into x from transfers where ticket_id = t.id and status in ('code_active', 'pending_admin') for update;
  if found then
    if x.status = 'pending_admin' then return jsonb_build_object('ok', false, 'error', 'ALREADY_PENDING'); end if;
    update transfers set status = 'replaced', updated_at = now() where id = x.id;
    perform _tlog('private transfer: code replaced', lbl, left(x.id::text, 8));
  end if;
  begin
    code := _new_transfer_code();
    insert into transfers (kind, ticket_id, booking_id, seller_name, seller_phone, status, code, code_expires_at)
    values ('private', t.id, b.id, t.name, t.phone, 'code_active', code, now() + make_interval(hours => s.private_code_hours))
    returning * into x;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'TRY_AGAIN');
  end;
  perform _tlog('private transfer: code created', null, lbl || ' (' || left(x.id::text, 8) || ')');
  return jsonb_build_object('ok', true, 'code', x.code, 'expires_at', x.code_expires_at,
                            'hours', s.private_code_hours, 'ticket_label', lbl);
end $function$;

CREATE OR REPLACE FUNCTION public.public_sell(p_booking_code text, p_ticket text, p_phone text, p_upi text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; tid uuid; t tickets%rowtype; b bookings%rowtype; x transfers%rowtype; code text; lbl text; blocked text; upi text;
begin
  select * into s from settings where id = 1;
  if not s.transfers_open then return jsonb_build_object('ok', false, 'error', 'TRANSFERS_CLOSED'); end if;
  if s.transfer_cutoff_at is not null and now() > s.transfer_cutoff_at then
    return jsonb_build_object('ok', false, 'error', 'CUTOFF_PASSED'); end if;
  tid := _find_seller_ticket(p_booking_code, p_ticket, p_phone);
  if tid is null then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into t from tickets where id = tid for update;
  select * into b from bookings where id = t.booking_id;
  if t.transferred_out_at is not null then return jsonb_build_object('ok', false, 'error', 'ALREADY_TRANSFERRED'); end if;
  if b.status <> 'paid' or (t.ticket_no is null and t.coord_no is null) then return jsonb_build_object('ok', false, 'error', 'NOT_CONFIRMED'); end if;
  if t.checked_in_at is not null then return jsonb_build_object('ok', false, 'error', 'ALREADY_CHECKED_IN'); end if;
  upi := btrim(coalesce(p_upi, ''));
  if upi !~ '^([0-9]{10}|[A-Za-z0-9._-]{2,64}@[A-Za-z][A-Za-z0-9]{1,31})$' then return jsonb_build_object('ok', false, 'error', 'INVALID_UPI'); end if;
  lbl := _ticket_label(t.kind, t.ticket_no, t.coord_no);
  select * into x from transfers where ticket_id = t.id and status in ('code_active', 'pending_admin') for update;
  if found then
    if x.status = 'pending_admin' then return jsonb_build_object('ok', false, 'error', 'ALREADY_PENDING'); end if;
    update transfers set status = 'replaced', updated_at = now() where id = x.id;
    perform _tlog('public transfer: code replaced', lbl, left(x.id::text, 8));
  end if;
  begin
    code := _new_transfer_code();
    insert into transfers (kind, ticket_id, booking_id, seller_name, seller_phone, status, code, code_expires_at, seller_upi)
    values ('public', t.id, b.id, t.name, t.phone, 'code_active', code, now() + make_interval(hours => s.private_code_hours), upi)
    returning * into x;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'TRY_AGAIN');
  end;
  perform _tlog('public transfer: code created', null, lbl || ' (' || left(x.id::text, 8) || ')');
  return jsonb_build_object('ok', true, 'mode', 'public', 'code', x.code, 'expires_at', x.code_expires_at,
                            'hours', s.private_code_hours, 'ticket_label', lbl);
end $function$;

CREATE OR REPLACE FUNCTION public.registration_heartbeat(p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; st jsonb;
begin
  if p_session is null then raise exception 'INVALID_DATA'; end if;
  select * into s from settings where id = 1;
  st := _public_state(s, p_session);
  if (st->>'accepting')::boolean then
    insert into reg_sessions (id) values (p_session)
    on conflict (id) do update set last_seen = now();
    delete from reg_sessions where last_seen < now() - interval '1 day';
  else
    -- while closed, only a person who is still inside their grace minutes gets refreshed; nobody new can start
    if (st->>'grace_until') is not null then
      update reg_sessions set last_seen = now() where id = p_session;
    end if;
  end if;
  return st;
end $function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_booking_status(p_booking uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;
  if p_status not in ('pending','paid','rejected') then raise exception 'INVALID_STATUS'; end if;
  perform 1 from settings where id = 1 for update;
  -- transfer bookings are moved only by the transfer tools (they hold no ticket until approved)
  if exists (select 1 from bookings where id = p_booking and kind = 'transfer') then raise exception 'USE_TRANSFER_TOOLS'; end if;
  update bookings set status = p_status, reviewed_by = auth.uid(), reviewed_at = now(), reviewed_via = 'admin'
  where id = p_booking;
  if p_status = 'paid' then perform _assign_numbers(p_booking);
  else perform _close_open_transfers(p_booking, 'seller booking was set to ' || p_status); end if;
end $function$;

CREATE OR REPLACE FUNCTION public.set_coordinator(p_ticket_id uuid, p_make boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; t tickets%rowtype; bs text;
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;
  select * into s from settings where id = 1 for update;
  select * into t from tickets where id = p_ticket_id for update;
  if not found then raise exception 'INVALID_TICKET'; end if;
  if t.transferred_out_at is not null then raise exception 'ALREADY_TRANSFERRED'; end if;   -- a retired ticket can never become (or stop being) a coordinator

  if p_make and t.kind = 'guest' then
    if t.prev_coord_no is not null then
      -- this person was a coordinator before: they get their own old number and QR back
      update tickets set kind = 'coordinator', coord_no = t.prev_coord_no,
        orig_secret = t.secret,
        secret = coalesce(t.prev_coord_secret, substr(replace(gen_random_uuid()::text, '-', ''), 1, 12)),
        prev_coord_no = null, prev_coord_secret = null,
        marked_by = auth.uid(), marked_at = now() where id = t.id;
    else
      -- first time: next new coordinator number. Any guest number stays on record, cancelled while coordinator.
      update tickets set kind = 'coordinator', coord_no = s.next_coord, orig_secret = t.secret,
        secret = substr(replace(gen_random_uuid()::text, '-', ''), 1, 12),
        marked_by = auth.uid(), marked_at = now() where id = t.id;
      update settings set next_coord = next_coord + 1 where id = 1;
    end if;
  elsif not p_make and t.kind = 'coordinator' then
    -- the coordinator number is kept on this person (cancelled), never given to anyone else.
    -- the guest number and original QR come back, or a new guest number is given once paid.
    update tickets set kind = 'guest', prev_coord_no = t.coord_no, prev_coord_secret = t.secret,
      coord_no = null, secret = coalesce(orig_secret, secret),
      orig_secret = null, marked_by = null, marked_at = null where id = t.id;
    select status into bs from bookings where id = t.booking_id;
    if bs = 'paid' then perform _assign_numbers(t.booking_id); end if;
  end if;

  select * into t from tickets where id = t.id;
  return jsonb_build_object('id', t.id, 'kind', t.kind, 'ticket_no', t.ticket_no,
                            'label', _ticket_label(t.kind, t.ticket_no, t.coord_no));
end $function$;

CREATE OR REPLACE FUNCTION public.submit_booking(p_submission_id uuid, p_people jsonb, p_screenshot_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; b bookings%rowtype; n int; used int; r record; code text; pi jsonb;
begin
  select * into b from bookings where submission_id = p_submission_id;
  if found then return _booking_json(b.id); end if;

  select * into s from settings where id = 1 for update;
  select * into b from bookings where submission_id = p_submission_id;
  if found then return _booking_json(b.id); end if;

  pi := _pause_info(s);
  if (not s.is_open or (pi->>'in_pause')::boolean or now() > s.deadline) then
    -- closed right now: only people who were already filling the form get the grace minutes (+30 s for upload time)
    if _grace_until(s, p_submission_id, interval '30 seconds') is null then
      raise exception 'REGISTRATION_CLOSED';
    end if;
  end if;
  if p_people is null or jsonb_typeof(p_people) <> 'array' then raise exception 'INVALID_DATA'; end if;
  n := jsonb_array_length(p_people);
  if n < 1 or n > s.max_group then raise exception 'INVALID_GROUP_SIZE'; end if;

  select count(*) into used from tickets t join bookings bk on bk.id = t.booking_id where bk.status <> 'rejected' and t.transferred_out_at is null;
  if used + n > s.cap then raise exception 'NOT_ENOUGH_SPOTS'; end if;

  for r in select value from jsonb_array_elements(p_people) loop
    if length(trim(coalesce(r.value->>'name',''))) not between 1 and 80 then raise exception 'INVALID_NAME'; end if;
    if coalesce(r.value->>'phone','') !~ '^[0-9]{10}$' then raise exception 'INVALID_PHONE'; end if;
    if coalesce(r.value->>'occ','') not in ('Article Assistant','Industrial Trainee','Employee','Student','Others') then raise exception 'INVALID_OCCUPATION'; end if;
    if length(trim(coalesce(r.value->>'occ_detail',''))) not between 1 and 100 then raise exception 'INVALID_OCCUPATION_DETAIL'; end if;
    if coalesce(r.value->>'loc','') not in ('In Bengaluru','Outside Bengaluru') then raise exception 'INVALID_LOCATION'; end if;
    if coalesce(r.value->>'food','') not in ('Veg','Non-veg') then raise exception 'INVALID_FOOD'; end if;
  end loop;

  if p_screenshot_path is null or p_screenshot_path not like p_submission_id::text || '%'
     or not exists (select 1 from storage.objects where bucket_id = 'payment-proofs' and name = p_screenshot_path)
  then raise exception 'SCREENSHOT_MISSING'; end if;

  loop
    code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    exit when not exists (select 1 from bookings where booking_code = code);
  end loop;

  insert into bookings (booking_code, submission_id, people_count, amount_expected, screenshot_path)
  values (code, p_submission_id, n, n * s.price_per_head, p_screenshot_path) returning * into b;
  insert into booking_ips (booking_id, ip, raw) values (b.id, _client_ip(), _client_ip_raw());   -- flag only, never blocks

  -- one ticket per person, in the order listed (no email, no attendance any more)
  for r in select value, ord from jsonb_array_elements(p_people) with ordinality as e(value, ord) order by ord loop
    insert into tickets (secret, booking_id, name, phone, location, food, occupation, occupation_detail)
    values (substr(replace(gen_random_uuid()::text, '-', ''), 1, 12), b.id,
            trim(r.value->>'name'), r.value->>'phone', r.value->>'loc', r.value->>'food',
            r.value->>'occ', trim(r.value->>'occ_detail'));
  end loop;

  return _booking_json(b.id);
end $function$;

CREATE OR REPLACE FUNCTION public.submit_feedback(p_booking_code text, p_rating integer, p_comment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings; bid uuid; c text := nullif(trim(coalesce(p_comment, '')), '');
begin
  select * into s from settings where id = 1;
  if not s.ask_feedback then return jsonb_build_object('ok', false, 'error', 'FEEDBACK_OFF'); end if;
  if p_rating is not null and p_rating not between 1 and 5 then return jsonb_build_object('ok', false, 'error', 'INVALID_RATING'); end if;
  if c is not null and char_length(c) > 1000 then return jsonb_build_object('ok', false, 'error', 'INVALID_COMMENT'); end if;
  if p_rating is null and c is null then return jsonb_build_object('ok', false, 'error', 'EMPTY_FEEDBACK'); end if;
  select id into bid from bookings where booking_code = upper(trim(coalesce(p_booking_code, ''))) and kind = 'registration';
  if bid is null then return jsonb_build_object('ok', false, 'error', 'BOOKING_NOT_FOUND'); end if;
  insert into booking_feedback (booking_id, rating, comment) values (bid, p_rating, c)
    on conflict (booking_id) do update set rating = excluded.rating, comment = excluded.comment, updated_at = now();
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_cancel(p_booking_code text, p_ticket text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tid uuid; x transfers%rowtype;
begin
  tid := _find_seller_ticket(p_booking_code, p_ticket, p_phone);
  if tid is null then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into x from transfers where ticket_id = tid and status in ('code_active', 'pending_admin') for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'NOTHING_TO_CANCEL'); end if;
  if x.status = 'pending_admin' then return jsonb_build_object('ok', false, 'error', 'CONTACT_ADMIN'); end if;
  update transfers set status = 'withdrawn', updated_at = now() where id = x.id;
  perform _tlog('private transfer: cancelled by seller', 'code_active', left(x.id::text, 8));
  return jsonb_build_object('ok', true);
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_open(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; c text; x transfers%rowtype; t tickets%rowtype; b bookings%rowtype;
begin
  select * into s from settings where id = 1;
  if not s.transfers_open then return jsonb_build_object('ok', false, 'error', 'TRANSFERS_CLOSED'); end if;
  if s.transfer_cutoff_at is not null and now() > s.transfer_cutoff_at then
    return jsonb_build_object('ok', false, 'error', 'CUTOFF_PASSED'); end if;
  c := upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'));
  if c !~ '^[A-Z2-9]{6}$' then return jsonb_build_object('ok', false, 'error', 'INVALID_CODE'); end if;
  select * into x from transfers where code = c and status = 'code_active' and code_expires_at > now();
  if not found then return jsonb_build_object('ok', false, 'error', 'INVALID_CODE'); end if;
  select * into t from tickets where id = x.ticket_id;
  select * into b from bookings where id = t.booking_id;
  if t.transferred_out_at is not null or t.checked_in_at is not null or b.status <> 'paid' then
    return jsonb_build_object('ok', false, 'error', 'NOT_AVAILABLE'); end if;
  return jsonb_build_object('ok', true, 'mode', x.kind, 'seller_name', t.name, 'expires_at', x.code_expires_at,
                            'food_locked', s.transfer_food_locked,
                            'food', case when s.transfer_food_locked then t.food end);
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_pay(p_booking_code text, p_phone text, p_submission_id uuid, p_screenshot_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; ph text; b bookings%rowtype; bu transfer_buyers%rowtype; x transfers%rowtype; s settings%rowtype;
begin
  c  := replace(replace(replace(upper(coalesce(p_booking_code, '')), 'O', '0'), ' ', ''), '-', '');
  ph := replace(replace(coalesce(p_phone, ''), ' ', ''), '-', '');
  if length(c) <> 8 or ph !~ '^[0-9]{10}$' or p_submission_id is null then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into b from bookings where booking_code = c and kind = 'transfer';
  if not found then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into bu from transfer_buyers where booking_id = b.id and phone = ph;
  if not found then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  select * into x from transfers where id = bu.transfer_id and kind = 'public' for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'MISMATCH'); end if;
  if x.payment_submission_id = p_submission_id then return jsonb_build_object('ok', true, 'replay', true, 'amount_due', x.amount_due); end if;
  select * into s from settings where id = 1;
  if not s.transfers_open then return jsonb_build_object('ok', false, 'error', 'TRANSFERS_CLOSED'); end if;
  if x.status <> 'pending_admin' then return jsonb_build_object('ok', false, 'error', 'NOT_ACTIVE'); end if;
  if x.payment_requested_at is null then return jsonb_build_object('ok', false, 'error', 'PAYMENT_NOT_REQUESTED'); end if;
  if x.payment_submitted_at is not null then return jsonb_build_object('ok', false, 'error', 'ALREADY_SUBMITTED'); end if;
  if p_screenshot_path is null or p_screenshot_path not like p_submission_id::text || '%'
     or not exists (select 1 from storage.objects where bucket_id = 'payment-proofs' and name = p_screenshot_path) then
    return jsonb_build_object('ok', false, 'error', 'SCREENSHOT_MISSING'); end if;
  update transfers set payment_submission_id = p_submission_id, payment_screenshot_path = p_screenshot_path,
         payment_submitted_at = now(), updated_at = now() where id = x.id;
  perform _tlog('public transfer: buyer payment submitted', null, x.amount_due::text || ' due (' || left(x.id::text, 8) || ')');
  return jsonb_build_object('ok', true, 'amount_due', x.amount_due);
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_status(p_booking_code text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; ph text; b bookings%rowtype; res jsonb;
begin
  c  := replace(replace(replace(upper(coalesce(p_booking_code, '')), 'O', '0'), ' ', ''), '-', '');
  ph := replace(replace(coalesce(p_phone, ''), ' ', ''), '-', '');
  if length(c) <> 8 or ph !~ '^[0-9]{10}$' then return jsonb_build_object('found', false); end if;
  select * into b from bookings where booking_code = c;
  if not found or not exists (select 1 from tickets where booking_id = b.id and phone = ph) then
    return jsonb_build_object('found', false); end if;
  select coalesce(jsonb_agg(r.j order by r.created_at desc), '[]'::jsonb) into res from (
    select x.created_at, jsonb_build_object(
        'ticket_label', _ticket_label(tk.kind, tk.ticket_no, tk.coord_no), 'mode', x.kind,
        'status', case when x.status = 'code_active' and x.code_expires_at <= now() then 'expired' else x.status end,
        'code', case when x.status = 'code_active' and x.code_expires_at > now() then x.code end,
        'expires_at', case when x.status = 'code_active' then x.code_expires_at end,
        'buyer_name', case when x.status in ('pending_admin', 'done')
                           then (select bu.name from transfer_buyers bu where bu.transfer_id = x.id and bu.status in ('active', 'done') limit 1) end,
        'payout', case when x.kind = 'public' and x.status = 'done' then case when x.seller_paid_at is not null then 'paid' else 'to_be_paid' end end,
        'amount_to_receive', case when x.kind = 'public' and x.status = 'done' then x.amount_received end,
        'created_at', x.created_at) as j
      from transfers x join tickets tk on tk.id = x.ticket_id
     where x.booking_id = b.id and x.seller_phone = ph
     order by x.created_at desc limit 10) r;
  return jsonb_build_object('found', true, 'transfers', res);
end $function$;

CREATE OR REPLACE FUNCTION public.transfer_submit(p_code text, p_submission_id uuid, p_buyer jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; c text; x transfers%rowtype; t tickets%rowtype; sb bookings%rowtype; bu transfer_buyers%rowtype;
        bk bookings%rowtype; bcode text; v_food text; v_email text; v_name text;
begin
  if p_submission_id is null then return jsonb_build_object('ok', false, 'error', 'INVALID_DATA'); end if;
  -- the same submission again: give back the same answer (a retry after a bad connection)
  select * into bu from transfer_buyers where submission_id = p_submission_id;
  if found then
    select * into bk from bookings where id = bu.booking_id;
    return jsonb_build_object('ok', true, 'booking_code', bk.booking_code, 'status', bk.status, 'replay', true);
  end if;

  select * into s from settings where id = 1;
  if not s.transfers_open then return jsonb_build_object('ok', false, 'error', 'TRANSFERS_CLOSED'); end if;
  if s.transfer_cutoff_at is not null and now() > s.transfer_cutoff_at then
    return jsonb_build_object('ok', false, 'error', 'CUTOFF_PASSED'); end if;
  c := upper(regexp_replace(coalesce(p_code, ''), '[\s-]', '', 'g'));
  if c !~ '^[A-Z2-9]{6}$' then return jsonb_build_object('ok', false, 'error', 'INVALID_CODE'); end if;

  if p_buyer is null or jsonb_typeof(p_buyer) <> 'object' then return jsonb_build_object('ok', false, 'error', 'INVALID_DATA'); end if;
  v_name := trim(coalesce(p_buyer->>'name', ''));
  v_email := case when s.ask_email then lower(trim(coalesce(p_buyer->>'email', ''))) else null end;
  if length(v_name) not between 1 and 80 then return jsonb_build_object('ok', false, 'error', 'INVALID_NAME'); end if;
  if coalesce(p_buyer->>'phone', '') !~ '^[0-9]{10}$' then return jsonb_build_object('ok', false, 'error', 'INVALID_PHONE'); end if;
  if s.ask_email and (length(v_email) not between 5 and 120 or v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$') then return jsonb_build_object('ok', false, 'error', 'INVALID_EMAIL'); end if;
  if coalesce(p_buyer->>'loc', '') not in ('In Bengaluru', 'Outside Bengaluru') then return jsonb_build_object('ok', false, 'error', 'INVALID_LOCATION'); end if;
  if coalesce(p_buyer->>'att', '') not in ('Surely', 'Most probably') then return jsonb_build_object('ok', false, 'error', 'INVALID_ATTENDANCE'); end if;
  if not s.transfer_food_locked and coalesce(p_buyer->>'food', '') not in ('Veg', 'Non-veg') then return jsonb_build_object('ok', false, 'error', 'INVALID_FOOD'); end if;
  if coalesce(p_buyer->>'consent', '') <> 'true' then return jsonb_build_object('ok', false, 'error', 'INVALID_CONSENT'); end if;

  -- first valid submission wins
  select * into x from transfers where code = c and status = 'code_active' and code_expires_at > now() for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'INVALID_CODE'); end if;
  select * into t from tickets where id = x.ticket_id for update;
  select * into sb from bookings where id = t.booking_id;
  if t.transferred_out_at is not null or t.checked_in_at is not null or sb.status <> 'paid' then
    return jsonb_build_object('ok', false, 'error', 'NOT_AVAILABLE'); end if;
  v_food := case when s.transfer_food_locked then t.food else p_buyer->>'food' end;

  begin
    loop
      bcode := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
      exit when not exists (select 1 from bookings where booking_code = bcode);
    end loop;
    insert into bookings (booking_code, submission_id, people_count, amount_expected, screenshot_path, kind)
    values (bcode, p_submission_id, 1, 0, null, 'transfer') returning * into bk;
    insert into transfer_buyers (transfer_id, submission_id, booking_id, name, phone, email, location, attendance, food, consent_at)
    values (x.id, p_submission_id, bk.id, v_name, p_buyer->>'phone', v_email, p_buyer->>'loc', p_buyer->>'att', v_food, now());
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'error', 'TRY_AGAIN');
  end;
  update transfers set status = 'pending_admin', updated_at = now() where id = x.id;
  perform _tlog('private transfer: buyer submitted', 'code_active', _ticket_label(t.kind, t.ticket_no, t.coord_no) || ' (' || left(x.id::text, 8) || ')');
  return jsonb_build_object('ok', true, 'mode', x.kind, 'booking_code', bk.booking_code, 'status', 'pending',
                            'seller_name', t.name, 'food', v_food);
end $function$;

CREATE OR REPLACE FUNCTION public.undo_checkin(p_ticket_no integer DEFAULT NULL::integer, p_coord boolean DEFAULT false, p_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;

  if p_id is not null then
    update tickets set checked_in_at = null, checked_in_by = null
    where id = p_id;
  elsif p_coord then
    update tickets set checked_in_at = null, checked_in_by = null
    where coord_no = p_ticket_no and kind = 'coordinator';
  else
    update tickets set checked_in_at = null, checked_in_by = null
    where ticket_no = p_ticket_no;
  end if;

  get diagnostics n = row_count;
  if n = 0 then raise exception 'INVALID_TICKET'; end if;
end $function$;

CREATE OR REPLACE FUNCTION public._assign_numbers(p_booking uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s settings%rowtype; r record;
begin
  select * into s from settings where id = 1 for update;
  for r in select id from tickets where booking_id = p_booking and kind = 'guest' and ticket_no is null order by reg_seq loop
    update tickets set ticket_no = s.next_ticket where id = r.id;
    s.next_ticket := s.next_ticket + 1;
  end loop;
  update settings set next_ticket = s.next_ticket where id = 1;
end $function$;

CREATE OR REPLACE FUNCTION public._client_ip()
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare ip text; xff text; parts text[];
begin
  ip := _clean_ip(_header('cf-connecting-ip'));
  if ip is not null then return ip; end if;
  xff := _header('x-forwarded-for');
  if xff is not null then
    parts := string_to_array(replace(xff, ' ', ''), ',');
    ip := _clean_ip(parts[array_length(parts, 1)]);
  end if;
  return ip;
end $function$;

CREATE OR REPLACE FUNCTION public._close_moment(s settings)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare pi jsonb := _pause_info(s);
begin
  return least(case when not s.is_open then s.closed_at end,
               case when (pi->>'in_pause')::boolean then (pi->>'last_close')::timestamptz end,
               case when now() > s.deadline then s.deadline end);
end $function$;

CREATE OR REPLACE FUNCTION public._close_open_transfers(p_booking uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare x record; due boolean;
begin
  for x in select id, status, kind, payment_submitted_at from transfers where booking_id = p_booking
           and status in ('code_active', 'pending_admin') for update loop
    due := x.kind = 'public' and x.payment_submitted_at is not null;
    update transfers set status = 'withdrawn', decision_note = left(p_reason, 300), decided_at = now(),
           decided_by = auth.uid(), updated_at = now(), return_due = (return_due or due) where id = x.id;
    update bookings set status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(), reviewed_via = 'admin'
     where id in (select booking_id from transfer_buyers where transfer_id = x.id and status = 'active');
    update transfer_buyers set status = 'released' where transfer_id = x.id and status = 'active';
    perform _tlog(x.kind || ' transfer closed automatically', x.status, left(x.id::text, 8) || ': ' || p_reason || case when due then ' (RETURN DUE)' else '' end);
  end loop;
end $function$;

CREATE OR REPLACE FUNCTION public._find_seller_ticket(p_code text, p_ticket text, p_phone text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c text; ph text; k text; n int; v uuid;
begin
  c  := replace(replace(replace(upper(coalesce(p_code, '')), 'O', '0'), ' ', ''), '-', '');
  ph := replace(replace(coalesce(p_phone, ''), ' ', ''), '-', '');
  if length(c) <> 8 or ph !~ '^[0-9]{10}$' then return null; end if;
  select pt.kind, pt.no into k, n from _parse_ticket(p_ticket) pt;
  if k is null then return null; end if;
  select t.id into v from tickets t join bookings b on b.id = t.booking_id
   where b.booking_code = c and t.phone = ph   -- a ticket received by transfer can be sold on too
     and ((k = 'guest' and t.kind = 'guest' and t.ticket_no = n)
       or (k = 'coordinator' and t.kind = 'coordinator' and t.coord_no = n));
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public._grace_until(s settings, p_session uuid, p_slack interval DEFAULT '00:00:00'::interval)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare cm timestamptz; r reg_sessions%rowtype;
begin
  if p_session is null then return null; end if;
  cm := _close_moment(s);
  if cm is null or now() > cm + make_interval(mins => s.grace_minutes) + p_slack then return null; end if;
  select * into r from reg_sessions where id = p_session;
  if not found or r.started_at >= cm or r.last_seen < cm - interval '10 minutes' then return null; end if;
  if exists (select 1 from bookings where submission_id = p_session) then return null; end if;
  return cm + make_interval(mins => s.grace_minutes);
end $function$;

CREATE OR REPLACE FUNCTION public._log_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare k text; o jsonb := to_jsonb(old); n jsonb := to_jsonb(new); uid uuid := auth.uid(); nm text;
begin
  select name into nm from staff where user_id = uid;
  for k in select jsonb_object_keys(n) loop
    if k in ('next_ticket', 'next_coord', 'closed_at') then continue; end if;
    if o -> k is distinct from n -> k then
      insert into settings_log (changed_by, who, area, field, old_value, new_value)
      values (uid, coalesce(nm, case when uid is null then 'database' else 'unknown login' end),
              'settings', k, o ->> k, n ->> k);
    end if;
  end loop;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public._log_staff_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare uid uuid := auth.uid(); nm text; w text;
begin
  select name into nm from staff where user_id = uid;
  w := coalesce(nm, case when uid is null then 'database' else 'unknown login' end);
  if tg_op = 'INSERT' then
    insert into settings_log (changed_by, who, area, field, old_value, new_value)
    values (uid, w, 'staff', 'added', null, new.name || ' (' || new.role || ')');
  elsif tg_op = 'DELETE' then
    insert into settings_log (changed_by, who, area, field, old_value, new_value)
    values (uid, w, 'staff', 'removed', old.name || ' (' || old.role || ')', null);
  else
    if old.role is distinct from new.role then
      insert into settings_log (changed_by, who, area, field, old_value, new_value)
      values (uid, w, 'staff', 'role of ' || new.name, old.role, new.role);
    end if;
    if old.name is distinct from new.name then
      insert into settings_log (changed_by, who, area, field, old_value, new_value)
      values (uid, w, 'staff', 'name', old.name, new.name);
    end if;
  end if;
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public._new_transfer_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare alpha constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; bytes bytea; c text; i int;
begin
  loop
    bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    c := '';
    for i in 0..5 loop c := c || substr(alpha, (get_byte(bytes, i) % 32) + 1, 1); end loop;
    exit when not exists (select 1 from transfers where code = c and status = 'code_active');
  end loop;
  return c;
end $function$;

CREATE OR REPLACE FUNCTION public._parse_ticket(p text, OUT kind text, OUT no integer)
 RETURNS record
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare s text;
begin
  s := upper(regexp_replace(coalesce(p, ''), '[\s-]', '', 'g'));
  s := regexp_replace(s, '^E26', '');
  s := replace(s, 'O', '0');
  if s ~ '^[0-9]{1,6}C$' then kind := 'coordinator'; no := substr(s, 1, length(s) - 1)::integer;
  elsif s ~ '^[0-9]{1,6}$' then kind := 'guest'; no := s::integer;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public._pause_info(s settings)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare ist_now timestamp; lc timestamp; op timestamp;
begin
  if not s.pause_enabled then
    return jsonb_build_object('in_pause', false, 'last_close', null, 'next_open', null, 'next_close', null);
  end if;
  ist_now := now() at time zone 'Asia/Kolkata';
  lc := ist_now::date + s.pause_close_time;
  if lc > ist_now then lc := lc - interval '1 day'; end if;      -- most recent close moment
  op := lc::date + s.pause_open_time;
  if op <= lc then op := op + interval '1 day'; end if;           -- the reopen that follows it
  return jsonb_build_object(
    'in_pause',   ist_now < op,
    'last_close', lc at time zone 'Asia/Kolkata',
    'next_open',  op at time zone 'Asia/Kolkata',
    'next_close', (lc + interval '1 day') at time zone 'Asia/Kolkata');
end $function$;

CREATE OR REPLACE FUNCTION public._public_state(s settings, p_session uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare used int; remaining int; reason text; pi jsonb; gu timestamptz; reopen timestamptz;
begin
  select count(*) into used from tickets t join bookings b on b.id = t.booking_id where b.status <> 'rejected' and t.transferred_out_at is null;
  remaining := greatest(s.cap - used, 0);
  pi := _pause_info(s);
  reason := case when not s.is_open then 'not_open'
                 when now() > s.deadline then 'deadline'
                 when remaining = 0 then 'full'
                 when (pi->>'in_pause')::boolean then 'paused'
                 else null end;
  reopen := case when reason = 'paused' and (pi->>'next_open')::timestamptz <= s.deadline
                 then (pi->>'next_open')::timestamptz else null end;
  if reason = 'paused' and reopen is null then reason := 'deadline'; end if;
  gu := case when reason in ('not_open', 'paused', 'deadline') then _grace_until(s, p_session) else null end;
  return jsonb_build_object('accepting', reason is null, 'closed_reason', reason,
    'spots_left', remaining, 'price_per_head', s.price_per_head,
    'max_group', greatest(least(s.max_group, remaining), 1), 'deadline', s.deadline,
    'server_now', now(), 'grace_until', gu, 'reopen_at', reopen,
    'pause_enabled', s.pause_enabled,
    'next_close_at', case when reason is null and s.pause_enabled and (pi->>'next_close')::timestamptz < s.deadline
                          then (pi->>'next_close')::timestamptz else null end);
end $function$;

CREATE OR REPLACE FUNCTION public._request_headers()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare h text;
begin
  h := current_setting('request.headers', true);
  if h is null or h = '' then return '{}'::jsonb; end if;
  begin return h::jsonb; exception when others then return '{}'::jsonb; end;
end $function$;

CREATE OR REPLACE FUNCTION public.admin_approve_bookings(p_ids uuid[], p_expected_next integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s_next int; r record; b bookings%rowtype; t record;
  ok_rows jsonb := '[]'::jsonb; skip_rows jsonb := '[]'::jsonb; ppl jsonb;
  n_ok int := 0; n_people int := 0; n_amt bigint := 0;
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;
  if p_ids is null or cardinality(p_ids) = 0 then raise exception 'NO_BOOKINGS'; end if;
  if cardinality(p_ids) > 200 then raise exception 'TOO_MANY'; end if;
  -- same lock as set_booking_status: nobody else hands out numbers while this runs
  perform 1 from settings where id = 1 for update;
  select next_ticket into s_next from settings where id = 1;
  if p_expected_next is not null and p_expected_next <> s_next then
    raise exception 'NUMBERS_CHANGED' using detail = 'The next free ticket number is now ' || s_next || ', not ' || p_expected_next || '. Nothing was approved.';
  end if;
  for r in select id from (select u.id, min(u.ord) o from unnest(p_ids) with ordinality u(id, ord) group by u.id) q order by o loop
    select * into b from bookings where id = r.id for update;
    if not found then
      skip_rows := skip_rows || jsonb_build_object('booking_id', r.id, 'reason', 'NOT_FOUND');
    elsif b.kind = 'transfer' then
      skip_rows := skip_rows || jsonb_build_object('booking_id', b.id, 'booking_code', b.booking_code, 'reason', 'TRANSFER');
    elsif b.status <> 'pending' then
      skip_rows := skip_rows || jsonb_build_object('booking_id', b.id, 'booking_code', b.booking_code, 'reason', 'NOT_PENDING', 'status', b.status);
    else
      -- exactly what set_booking_status does for 'paid'
      update bookings set status = 'paid', reviewed_by = auth.uid(), reviewed_at = now(), reviewed_via = 'admin'
      where id = b.id;
      perform _assign_numbers(b.id);
      ppl := '[]'::jsonb;
      for t in select name, ticket_no from tickets where booking_id = b.id order by reg_seq loop
        ppl := ppl || jsonb_build_object('name', t.name, 'ticket_no', t.ticket_no);
      end loop;
      ok_rows := ok_rows || jsonb_build_object('booking_id', b.id, 'booking_code', b.booking_code, 'people_count', b.people_count, 'amount', b.amount_expected, 'people', ppl);
      n_ok := n_ok + 1; n_people := n_people + b.people_count; n_amt := n_amt + b.amount_expected;
    end if;
  end loop;
  return jsonb_build_object('approved', ok_rows, 'skipped', skip_rows, 'bookings', n_ok, 'people', n_people, 'amount', n_amt);
end $function$;

CREATE OR REPLACE FUNCTION public.admin_assign_messages(p_pairs jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; cnt int; summ text; ids_t uuid[]; ids_m uuid[];
begin
  if not is_admin() then raise exception 'NOT_ALLOWED'; end if;
  if p_pairs is null or jsonb_typeof(p_pairs) <> 'array' then raise exception 'INVALID_PAIRS'; end if;
  cnt := jsonb_array_length(p_pairs);
  if cnt = 0 then return 0; end if;
  if cnt > 1000 then raise exception 'TOO_MANY'; end if;
  begin
    select array_agg((e->>'t')::uuid), array_agg((e->>'m')::uuid) into ids_t, ids_m from jsonb_array_elements(p_pairs) e;
  exception when others then raise exception 'INVALID_PAIRS';
  end;
  if array_position(ids_t, null) is not null or array_position(ids_m, null) is not null then raise exception 'INVALID_PAIRS'; end if;
  if (select count(distinct x) from unnest(ids_t) x) <> cnt then raise exception 'DUPLICATE_TICKET'; end if;
  if (select count(*) from tickets where id = any (ids_t) and transferred_out_at is null) <> cnt then raise exception 'TICKET_NOT_FOUND'; end if;
  if (select count(*) from game_messages where id = any (ids_m)) <> (select count(distinct x) from unnest(ids_m) x) then raise exception 'MESSAGE_NOT_FOUND'; end if;
  insert into ticket_messages (ticket_id, message_id)
    select t, m from unnest(ids_t, ids_m) as u(t, m)
    on conflict (ticket_id) do update set message_id = excluded.message_id, assigned_at = now();
  get diagnostics n = row_count;
  select string_agg(g.name || ' x' || c.k, ', ' order by g.name) into summ
    from (select m, count(*) k from unnest(ids_m) m group by m) c join game_messages g on g.id = c.m;
  perform _mlog('messages given', null, n || ' ticket(s): ' || summ);
  return n;
end $function$;

